window.HOEREN_TESTS[66] = {"id":"im-zoo","name":"Im Zoo","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Besucher: Willkommen im Zoo. Die Fütterung der Pinguine ist heute nicht um 14 Uhr und nicht um 15 Uhr, sondern schon um 13 Uhr. Die Löwen-Fütterung bleibt um 15 Uhr. Bitte stören Sie die Tiere nicht und füttern Sie sie nicht selbst. Wir wünschen einen schönen Tag im Zoo!","gender":"f","q":"Wann ist die Pinguin-Fütterung heute?","opts":["Um 14 Uhr.","Um 13 Uhr.","Um 15 Uhr."],"correct":1},{"transcript":"Hallo Mama, hier ist Anna. Wir sind im Zoo und es ist toll! Die Kinder lieben die Affen. Aber das Elefantenhaus ist heute geschlossen, wegen Reinigung. Das Affenhaus und der Zoo-Shop sind offen. Schade, die Elefanten wollten sie sehen. Wir bleiben noch bis 17 Uhr. Soll ich dir was aus dem Zoo-Shop mitbringen? Tschüs!","gender":"f","q":"Was ist heute geschlossen?","opts":["Das Affenhaus.","Das Elefantenhaus.","Der Zoo-Shop."],"correct":1},{"transcript":"Achtung Besucher: Wir haben Nachwuchs im Zoo! Bei den Eisbären ist ein Baby geboren, nicht beim Löwen und nicht beim Affen. Es ist aber noch zu klein und bleibt mit der Mutter hinten. Erst in zwei Monaten könnt ihr es sehen. Auf unserer Internetseite gibt es schon erste Fotos. Wir freuen uns mit euch!","gender":"m","q":"Welches Tier hat ein Baby bekommen?","opts":["Der Löwe.","Der Affe.","Der Eisbär."],"correct":2},{"transcript":"Hi Tom, hier ist Markus. Also, am Samstag gehe ich mit meinem Sohn in den Zoo. Es gibt eine Führung hinter die Kulissen — man sieht, wie die Tierpfleger arbeiten. Eine Bootsfahrt oder ein Picknick machen wir nicht. Die Führung kostet extra, aber lohnt sich. Kommt ihr mit deiner Tochter mit? Ruf zurück!","gender":"m","q":"Was möchte Markus am Samstag machen?","opts":["Eine Führung hinter die Kulissen.","Eine Bootsfahrt.","Ein Picknick."],"correct":0},{"transcript":"Liebe Gäste: Mit der Jahreskarte sparen Sie viel Geld. Ein Einzelticket kostet 20 Euro, die Jahreskarte nur 80 Euro, nicht 100 Euro. Wer mehr als viermal im Jahr kommt, spart also richtig. Kinder unter sechs Jahren haben immer freien Eintritt. Fragen Sie an der Kasse nach der Familienkarte!","gender":"f","q":"Was kostet die Jahreskarte?","opts":["20 Euro.","100 Euro.","80 Euro."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer mag welches Tier? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Zoo hat heute lange auf und der Plan steckt in meiner Tasche."},{"speaker":"Lisa","gender":"f","text":"Schön, dass wir den Weg vorbereiten. Die Kinder wollen einen klaren Rundgang."},{"speaker":"Lukas","gender":"m","text":"Ich gehe zuerst zu den Löwen. Der große Kater schläft oft vorn am Glas."},{"speaker":"Lisa","gender":"f","text":"Ich bleibe heute bei den Pinguinen. Sie springen ins Wasser und alle lachen jedes Mal."},{"speaker":"Lukas","gender":"m","text":"Wollen wir auch zu den Schlangen ins dunkle Haus?"},{"speaker":"Lisa","gender":"f","text":"Nein. Zu den Schlangen gehen wir nicht."},{"speaker":"Lukas","gender":"m","text":"Tom lacht immer bei dem lauten Gehege hinten links."},{"speaker":"Lisa","gender":"f","text":"Tom mag die Affen. Sie werfen bunte Bälle und schneiden wilde Grimassen."},{"speaker":"Lukas","gender":"m","text":"Hinten im Park stehen die hohen Bäume mit frischen Blättern."},{"speaker":"Lisa","gender":"f","text":"Sara mag die Giraffen. Der lange Hals reicht bis zu den oberen Blättern."},{"speaker":"Lukas","gender":"m","text":"Besuchen wir die Papageien im kleinen grünen Haus?"},{"speaker":"Lisa","gender":"f","text":"Nein. Die Papageien besuchen wir auch nicht. Dort ist es uns einfach zu laut."},{"speaker":"Lukas","gender":"m","text":"Tim bleibt lange bei den großen grauen Tieren am Wassergraben."},{"speaker":"Lisa","gender":"f","text":"Tim mag die Elefanten. Er schaut ihnen ruhig beim Baden zu."},{"speaker":"Lukas","gender":"m","text":"Dann starten wir zusammen am großen Eingang."},{"speaker":"Lisa","gender":"f","text":"Ich kaufe die Karten vorher noch am Fenster."}],"options":[{"letter":"a","text":"Papageien"},{"letter":"b","text":"Tiger"},{"letter":"c","text":"Elefanten"},{"letter":"d","text":"Pinguine"},{"letter":"e","text":"Löwen"},{"letter":"f","text":"Schlangen"},{"letter":"g","text":"Eisbären"},{"letter":"h","text":"Giraffen"},{"letter":"i","text":"Affen"}],"items":[{"person":"Lukas","correct":"e"},{"person":"Lisa","correct":"d"},{"person":"Tom","correct":"i"},{"person":"Sara","correct":"h"},{"person":"Tim","correct":"c"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Vater","gender":"m","text":"Guten Tag, was kostet der Eintritt für Kinder? Zahlen wir 10 Euro oder 5 Euro?"},{"speaker":"Kassiererin","gender":"f","text":"Ab sechs Jahren 10 Euro. Fünf Euro gibt es nicht."},{"speaker":"Vater","gender":"m","text":"Und unter sechs? Zahlt man dann auch etwas?"},{"speaker":"Kassiererin","gender":"f","text":"Nein, Kinder unter sechs zahlen nichts, die sind kostenlos."},{"speaker":"Vater","gender":"m","text":"Perfekt, meine Kleine ist vier. Dann zahle ich für sie nichts. Danke."}],"q":"Was zahlen Kinder unter sechs?","opts":["Nichts.","5 Euro.","10 Euro."],"correct":0},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, wo sind die Tiger? Neben den Affen oder neben den Pinguinen?"},{"speaker":"Vater","gender":"m","text":"Warte, schauen wir auf den Plan. Neben den Affen und neben den Pinguinen sind sie nicht."},{"speaker":"Tochter","gender":"f","text":"Da, neben den Löwen!"},{"speaker":"Vater","gender":"m","text":"Genau, neben den Löwen, gleich hier rechts. Komm, wir gehen dorthin."},{"speaker":"Tochter","gender":"f","text":"Super, dann sehen wir zuerst die Tiger und danach die Löwen."}],"q":"Wo sind die Tiger?","opts":["Neben den Affen.","Neben den Löwen.","Neben den Pinguinen."],"correct":1},{"lines":[{"speaker":"Besucherin","gender":"f","text":"Guten Tag, wann ist die Affen-Fütterung? Um 14 Uhr vielleicht?"},{"speaker":"Pfleger","gender":"m","text":"Nicht um 14 Uhr. Die Fütterung ist um 11 und um 16 Uhr."},{"speaker":"Besucherin","gender":"f","text":"Wann ist die erste Fütterung, um 11? Dürfen die Kinder zuschauen?"},{"speaker":"Pfleger","gender":"m","text":"Ja, die erste ist um 11 Uhr. Die Kinder dürfen zuschauen, aber bitte leise sein."},{"speaker":"Besucherin","gender":"f","text":"Gut, dann kommen wir um 11. Danke!"}],"q":"Wann ist die erste Affen-Fütterung?","opts":["Um 16 Uhr.","Um 14 Uhr.","Um 11 Uhr."],"correct":2},{"lines":[{"speaker":"Junge","gender":"m","text":"Mama, ich habe Hunger. Gibt es Essen am Eingang oder beim Elefantenhaus?"},{"speaker":"Mutter","gender":"f","text":"Am Eingang gibt es nur Eis, und beim Elefantenhaus nichts. Es gibt ein Restaurant am See."},{"speaker":"Junge","gender":"m","text":"Was gibt es da?"},{"speaker":"Mutter","gender":"f","text":"Pommes und Würstchen. Komm, wir gehen zum See, da essen wir."},{"speaker":"Junge","gender":"m","text":"Ja, am See ist gut. Ich möchte Pommes, bitte."}],"q":"Wo gibt es Essen?","opts":["Am See.","Am Eingang.","Beim Elefantenhaus."],"correct":0},{"lines":[{"speaker":"Besucher","gender":"m","text":"Guten Tag, darf ich die Ziegen füttern? Oder alle Tiere? Oder keine?"},{"speaker":"Pflegerin","gender":"f","text":"Nicht alle Tiere. Im Streichelzoo ja, nur die Ziegen, mit unserem Futter."},{"speaker":"Besucher","gender":"m","text":"Und die anderen Tiere draußen?"},{"speaker":"Pflegerin","gender":"f","text":"Nein, die anderen Tiere auf keinen Fall. Nur die Ziegen im Streichelzoo."},{"speaker":"Besucher","gender":"m","text":"Verstehe, nur die Ziegen im Streichelzoo. Danke."}],"q":"Welche Tiere darf man füttern?","opts":["Alle Tiere.","Nur die Ziegen im Streichelzoo.","Keine Tiere."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Vogel, einer Tierpflegerin im Zoo. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Vogel, wie sieht Ihr Tag als Tierpflegerin aus?"},{"speaker":"Vogel","gender":"f","text":"Ich fange früh an, um sechs Uhr. Erst füttere ich die Tiere, dann mache ich sauber. Der Morgen ist die wichtigste Zeit, weil die Tiere hungrig sind."},{"speaker":"Reporter","gender":"m","text":"Welche Tiere betreuen Sie vor allem?"},{"speaker":"Vogel","gender":"f","text":"Vor allem die Affen. Sie sind sehr klug. Ich kenne alle mit Namen und weiß, was jeder gern frisst. Das dauert Jahre, bis man sie so gut kennt."},{"speaker":"Reporter","gender":"m","text":"Ist die Arbeit gefährlich?"},{"speaker":"Vogel","gender":"f","text":"Bei manchen Tieren ja. Zu den großen Affen gehe ich nie allein, immer mit einem Kollegen. Das ist eine klare Regel bei uns im Zoo."},{"speaker":"Reporter","gender":"m","text":"Was wünschen Sie sich von den Besuchern?"},{"speaker":"Vogel","gender":"f","text":"Bitte füttern Sie die Tiere nicht. Falsches Essen macht sie krank. Und seien Sie leise, besonders bei den Jungtieren. Fotos machen ist okay, aber ohne Blitz."},{"speaker":"Reporter","gender":"m","text":"Warum sind Zoos heute wichtig?"},{"speaker":"Vogel","gender":"f","text":"Wir schützen Tiere, die es bald nicht mehr gibt. Und Kinder lernen viel über Tiere, wenn sie sie wirklich sehen. Ein Buch allein reicht da nicht. Deshalb ist der Zoo so wichtig für uns alle."}],"items":[{"q":"Frau Vogel kennt ihre Affen alle mit Namen.","correct":"ja"},{"q":"Sie geht allein zu den großen Affen.","correct":"nein"},{"q":"Sie fängt früh am Morgen mit der Arbeit an.","correct":"ja"},{"q":"Sie findet es gut, wenn Besucher die Tiere füttern.","correct":"nein"},{"q":"Zoos schützen Tiere, die es bald nicht mehr gibt.","correct":"ja"}]}]};
